state.output:
    &mut self,
    s: &NativeIntStr,
) -> Result<Vec<NativeIntString>, parse_error::ParseError> {
    let mut iterator = SplitIterator::new(s);

    macro_rules! map_parser_err {
        ($err:expr) => {{
            let err = $err;
            let pos = match err.err_type {
                ErrorType::EndOfInput | ErrorType::InternalError => err.peek_position,
            };
            parse_error::ParseError::InternalError { pos, sub_err: err }
        }};
    }

    macro_rules! current_char {
        () => {{
            let parser = &iterator.expander.parser;
            if parser.remaining.is_empty() || parser.pointer >= parser.input.len() {
                None
            } else {
                match parser.peek() {
                    Ok(c) => Some(c),
                    Err(err) => {
                        match err.err_type {
                            ErrorType::EndOfInput => None,
                            ErrorType::InternalError => return Err(map_parser_err!(err)),
                        }
                    }
                }
            }
        }};
    }

    macro_rules! skip_one {
        () => {{
            if let Err(err) = iterator
                .expander
                .parser
                .consume_one_ascii_or_all_non_ascii()
            {
                return Err(map_parser_err!(err));
            }
        }};
    }

    macro_rules! take_one {
        () => {{
            match iterator
                .expander
                .parser
                .consume_one_ascii_or_all_non_ascii()
            {
                Ok(chunks) => {
                    for chunk in chunks {
                        match chunk {
                            Chunk::InvalidEncoding(invalid) => {
                                iterator.expander.output.extend(invalid)
                            }
                            Chunk::ValidSingleIntChar((_c, ni)) => {
                                iterator.expander.output.push(ni)
                            }
                        }
                    }
                }
                Err(err) => return Err(map_parser_err!(err)),
            }
        }};
    }

    macro_rules! push_char {
        ($c:expr) => {{
            let os_str = OsString::from($c.to_string());
            let native = to_native_int_representation(&os_str);
            iterator.expander.output.extend(native.deref());
        }};
    }

    macro_rules! push_word {
        () => {{
            let word = mem::take(&mut iterator.expander.output);
            iterator.words.push(word);
        }};
    }

    macro_rules! replace_escape {
        ($c:expr) => {{
            if let Some((_, repl)) = REPLACEMENTS.iter().copied().find(|&(k, _)| k == $c) {
                skip_one!();
                push_char!(repl);
                true
            } else {
                false
            }
        }};
    }

    macro_rules! invalid_backslash {
        ($c:expr) => {
            parse_error::ParseError::InvalidSequenceBackslashXInMinusS {
                pos: iterator.expander.parser.pointer,
                c: $c,
            }
        };
    }

    macro_rules! substitute_variable {
        () => {{
            let mut var_parse = VariableParser {
                parser: &mut iterator.expander.parser,
            };
            let (name, default) = var_parse.parse_variable()?;
            let varname_os = from_native_int_representation(Cow::Borrowed(name));
            let named = NativeStr::new(&varname_os);
            let value = std::env::var_os(from_native_int_representation(named.native));
            match (&value, default) {
                (None, None) => {}
                (Some(value), _) => {
                    let native = to_native_int_representation(value);
                    iterator.expander.output.extend(native.deref());
                }
                (None, Some(default)) => {
                    iterator.expander.output.extend(default.iter().copied());
                }
            }
            let _ = var_parse.parser.peek();
        }};
    }

    enum SplitState {
        Delimiter,
        Unquoted,
        SingleQuoted,
        DoubleQuoted,
    }

    let mut state = SplitState::Delimiter;
    'split: loop {
        match state {
            SplitState::Delimiter => loop {
                match current_char!() {
                    None => break 'split,
                    Some('#') => {
                        skip_one!();
                        loop {
                            match current_char!() {
                                None => break 'split,
                                Some(NEW_LINE) => {
                                    skip_one!();
                                    break;
                                }
                                Some(_) => {
                                    let native_rep =
                                        get_single_native_int_value(&NEW_LINE).unwrap();
                                    let found = iterator
                                        .expander
                                        .parser
                                        .remaining
                                        .iter()
                                        .position(|x| *x == native_rep);
                                    if let Some(pos) = found {
                                        let new_ptr =
                                            iterator.expander.parser.pointer + pos;
                                        iterator.expander.parser.set_pointer(new_ptr);
                                    } else {
                                        let len = iterator.expander.parser.input.len();
                                        iterator.expander.parser.set_pointer(len);
                                    }
                                }
                            }
                        }
                    }
                    Some(BACKSLASH) => {
                        skip_one!();
                        match current_char!() {
                            None => {
                                return Err(
                                    parse_error::ParseError::InvalidBackslashAtEndOfStringInMinusS {
                                        pos: iterator.expander.parser.pointer,
                                        quoting: "Delimiter".into(),
                                    },
                                );
